import json, sys
sys.path.insert(0, __file__.rsplit('/', 1)[0])
from common import I, S, R

B = []
add = B.append
VICKY = dict(source_type='pdf', source_author='Victoria Melnik, vicky.school', category='Десерты', tags=['кондитерка'])

def vicky(ref, **kw):
    add(R(**{**VICKY, 'source_ref': ref, **kw}))

